"""Original COPD chapter: diagnosis, risk and maintenance treatment."""
from qbank_authoring import question,ref,finalize
GO=ref('GOLD Global Strategy for COPD, 2026 Final Report','https://goldcopd.org/wp-content/uploads/2025/12/GOLD-REPORT-2026-v1.3-8Dec2025_WMV.pdf')
ME=ref('NICE: Mepolizumab for Uncontrolled COPD With Raised Eosinophils, 2026','https://www.ncbi.nlm.nih.gov/books/NBK624530/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A patient with chronic dyspnea and relevant smoke exposure has post-bronchodilator FEV1/FVC 0.61. What does this support?', 'Persistent airflow obstruction consistent with COPD in the appropriate clinical context',[
 ('COPD is diagnosed from symptoms alone without spirometry','Objective obstruction is required in the diagnostic framework.'),('The ratio proves COPD is the only possible obstructive disease','Asthma and other causes remain possible.'),('A bronchodilator response would automatically exclude COPD','Responsiveness can occur in COPD.')],
 'Combine persistent obstruction with symptoms and exposure history', '**GOLD uses a post-bronchodilator ratio below 0.70 for diagnosis.**',['Age and the lower limit of normal affect interpretation near the threshold.','Borderline ratios can warrant repeat measurement.'], '**Assess alternate and coexisting disease.**',['Smoking is not the only exposure; biomass and other risks matter.','Document quality and the actual measured values.'],[['Physiology','Persistent post-BD obstruction'],['Context','Symptoms and risk exposure'],['Caution','Not an exclusive disease label']],[GO],'clinical_scenario')
q('Severe emphysema develops in a 39-year-old with modest smoke exposure and a basilar panacinar pattern. What inherited factor should be assessed?', 'Alpha-1 antitrypsin deficiency',[
 ('GCK-MODY','This does not explain the emphysema phenotype.'),('A high HDL concentration as the principal cause','This is not an emphysema mechanism.'),('No inherited assessment is relevant in COPD','Alpha-1 deficiency is an actionable consideration.')],
 'Early or disproportionate emphysema can signal protease-antiprotease imbalance', '**Alpha-1 antitrypsin protects tissue from neutrophil elastase.**',['GOLD supports testing people with COPD rather than only a narrow classic phenotype.','Liver disease and family implications also matter.'], '**Use level and appropriate genotype/phenotype confirmation.**',['Acute inflammation can affect the measured level.','Provide smoking avoidance and specialist counseling.'],[['Clue','Early/disproportionate emphysema'],['Protein','Alpha-1 antitrypsin'],['Implications','Lung, liver and relatives']],[GO],'clinical_scenario')
q('Why is FEV1 percent predicted insufficient by itself to choose initial COPD maintenance therapy?', 'Symptoms and exacerbation history provide additional treatment-relevant information',[
 ('Airflow obstruction has no clinical importance','It remains important but is not the only dimension.'),('All patients with the same FEV1 have identical symptoms and risk','They can differ markedly.'),('A CT scan replaces all symptom and event assessment','It does not.')],
 'Physiological grade and clinical treatment group answer different questions', '**CAT or dyspnea assessment captures burden.**',['Prior exacerbations predict future events.','Blood eosinophils help selected ICS decisions.'], '**Use a multidimensional assessment.**',['Include comorbidities, device ability and patient priorities.','Do not assign a whole regimen from one spirometry percentage.'],[['FEV1','Airflow grade'],['Symptoms','Burden'],['Exacerbations','Future risk and prevention priority']],[GO])
q('Before initial maintenance treatment, a COPD patient had one moderate exacerbation in the prior year. Which GOLD 2026 group applies?', 'Group E',[
 ('Group B solely because only one moderate event occurred','The 2026 criteria now place at least one moderate or severe event in E.'),('Group A regardless of event history','Prior exacerbation changes the group.'),('A GOLD airflow grade can substitute for the A/B/E group','The classifications represent different dimensions.')],
 'A current threshold differs from the older two-moderate-event rule', '**GOLD 2026 recognizes increased risk after even one moderate exacerbation.**',['The initial grouping also considers symptoms in patients without events.','Follow-up treatment is guided by persistent symptoms or exacerbations.'], '**Reassess preventive therapy after an event.**',['Do not apply an obsolete risk threshold.','Check diagnosis, technique and treatment access.'],[['Prior year','At least one moderate/severe event'],['2026 group','E'],['Implication','Exacerbation prevention priority']],[GO],'clinical_scenario')
q('A symptomatic COPD patient has no prior-year exacerbation and is suitable for GOLD Group B initial treatment. What is generally preferred?', 'LABA plus LAMA',[
 ('ICS monotherapy','This is not standard COPD initial maintenance.'),('A LABA without bronchodilator assessment because symptoms are irrelevant','Long-acting dual bronchodilation is preferred in this group.'),('Chronic oral prednisolone','Long-term systemic steroids have an unfavorable maintenance role.')],
 'Dual bronchodilation addresses symptoms through complementary receptors', '**LABA and LAMA can provide greater bronchodilation than one agent.**',['Device suitability and technique affect delivery.','An alternative may be needed if access or tolerance prevents the preferred regimen.'], '**Review benefit and adverse effects.**',['Check for cardiac, musculoskeletal and other contributors to breathlessness.','Medication complements rehabilitation and smoking cessation.'],[['Group B','Symptomatic without qualifying events'],['Preferred initial','LABA/LAMA'],['Follow-up','Response and delivery assessment']],[GO],'clinical_scenario')
q('An initial-treatment Group E COPD patient has blood eosinophils 380 cells/µL. Which additional consideration is supported by GOLD?', 'Consider LABA/LAMA/ICS triple therapy rather than assuming dual bronchodilation is the only option',[
 ('ICS alone is the preferred complete regimen','The COPD framework uses bronchodilator-based combination treatment.'),('Eosinophils prove an asthma diagnosis automatically','They inform Type 2/ICS response probability, not the entire diagnosis.'),('ICS has identical expected benefit at all eosinophil counts','The response relationship varies.')],
 'Exacerbation risk and inflammatory phenotype interact', '**GOLD considers initial triple therapy when eosinophils are at least 300.**',['LABA/LAMA remains the main initial approach for many Group E patients.','Pneumonia and other risks must be weighed.'], '**Use the count with history and clinical context.**',['Repeat or historical values can help when treatment suppresses counts.','Do not prescribe from eosinophils alone.'],[['Group E','Event-risk context'],['Eosinophils at least 300','Supports triple consideration'],['Balance','Benefit and ICS adverse effects']],[GO],'clinical_scenario')
q('What do blood eosinophils mainly help predict when deciding on ICS in COPD?', 'The probability of exacerbation-prevention benefit from adding ICS to bronchodilators',[
 ('An exact individual response guaranteed by one cutoff','The relationship is probabilistic and continuous.'),('The need for oxygen therapy','Oxygen is determined by gas-exchange criteria.'),('The presence of a bacterial infection in every case','Eosinophils do not establish that.')],
 'A biomarker informs a specific therapeutic outcome', '**Higher counts, especially around or above 300, support greater expected ICS benefit.**',['Counts below about 100 suggest lower likelihood of benefit.','Exacerbation history remains essential.'], '**Use the whole phenotype.**',['Coexisting asthma changes the ICS requirement.','Do not confuse symptom bronchodilation with steroid-mediated event prevention.'],[['Outcome','Exacerbation reduction'],['Higher eosinophils','Greater expected benefit'],['Context','History and asthma features']],[GO])
q('A COPD patient has repeated pneumonia while taking triple therapy. What is the appropriate ICS withdrawal principle?', 'Consider benefit-risk reassessment, recognizing that high eosinophils and prior exacerbations increase the risk of deterioration after withdrawal',[
 ('ICS can always be stopped without consequences','Some patients relapse, particularly with higher eosinophils.'),('Every pneumonia makes all inhaled treatment permanently contraindicated','Bronchodilator and individualized anti-inflammatory needs remain.'),('The decision is unrelated to any asthma history','Coexisting asthma is important.')],
 'A treatment complication requires a balanced review', '**Pneumonia is a recognized ICS concern in COPD.**',['Withdrawal risk is greater in some high-eosinophil phenotypes.','Check whether the current indication remains strong.'], '**Make a monitored regimen change if appropriate.**',['Preserve effective bronchodilation.','Reassess symptoms and attacks after the change.'],[['Harm','Pneumonia'],['Withdrawal risk','Eosinophils and event history'],['Plan','Individualized monitored decision']],[GO],'clinical_scenario')
q('A patient has persistent COPD-type obstruction and convincing coexisting asthma. What is an essential treatment principle?', 'Include appropriate ICS-containing asthma protection',[
 ('COPD physiology makes LABA monotherapy safe despite asthma','The asthma safety requirement remains.'),('Every inhaled steroid must be removed because obstruction is persistent','Asthma can develop persistent obstruction.'),('Only a smoking history determines treatment','Clinical phenotype matters.')],
 'Overlapping features do not erase asthma-related risk', '**Treat the asthma component according to an ICS-containing strategy.**',['Long-acting bronchodilators are selected for the obstructive burden.','The label alone should not replace careful diagnostic assessment.'], '**Review history and objective findings.**',['Do not diagnose overlap from eosinophils alone.','Use a safe integrated regimen and follow response.'],[['COPD component','Persistent obstruction'],['Asthma component','ICS safety requirement'],['Regimen','Integrated and phenotype based']],[GO])
q('Dyspnea persists on prescribed LABA/LAMA. What should be checked before adding several new medicines?', 'Inhaler technique, device suitability, adherence and other causes of breathlessness',[
 ('Assume two prescriptions prove full delivery','Technique and inspiratory ability can limit actual treatment.'),('Add ICS solely for every residual dyspnea without event context','ICS selection is chiefly linked to exacerbation benefit and phenotype.'),('Ignore heart failure and deconditioning','They can contribute substantially.')],
 'Symptoms can persist for reasons beyond airway drug choice', '**A dry-powder device requires an adequate inhalation maneuver.**',['Cost, dexterity and cognition affect use.','Hyperinflation and comorbidity require assessment.'], '**Optimize delivery and nonpharmacological care.**',['Consider device or molecule changes when appropriate.','Refer for rehabilitation and selected add-ons according to the treatment pathway.'],[['Delivery','Technique and suitable device'],['Other causes','Cardiac, fitness and systemic'],['Next step','Targeted rather than automatic escalation']],[GO],'clinical_scenario')
q('What is a major expected benefit of pulmonary rehabilitation in COPD?', 'Improved exercise capacity, symptoms and health status',[
 ('Permanent reversal of all emphysematous destruction','Rehabilitation does not regrow destroyed alveoli.'),('It replaces smoking cessation and vaccination','These remain complementary.'),('Only patients with normal mobility can participate','Programs can be adapted to limitations.')],
 'Functional treatment addresses consequences inhalers cannot fully correct', '**Training, education and behavior support improve activity tolerance.**',['Post-exacerbation rehabilitation is particularly important.','Nutrition, anxiety and self-management can be addressed.'], '**Make participation feasible.**',['Consider transport, home-based options and comorbid limitations.','Avoid using spirometry alone to deny a potentially useful program.'],[['Target','Function and symptoms'],['Components','Training and self-management'],['Timing','Stable disease and after exacerbations as appropriate']],[GO])
q('Which intervention remains central to reducing ongoing COPD risk in a person who smokes?', 'Evidence-based smoking-cessation support alongside disease treatment',[
 ('Inhalers remove the need to stop exposure','Exposure reduction remains critical.'),('Cessation is useless once obstruction is established','It can still improve the future course and health.'),('Brief blame-focused advice is the only effective method','Behavioral and pharmacological support can be combined.')],
 'A modifiable exposure affects more than lung function', '**Cessation reduces future tobacco-related harm.**',['Vaccination and exposure prevention add protection.','Other inhaled exposures, including household and occupational sources, deserve review.'], '**Offer practical treatment rather than an instruction alone.**',['Use suitable cessation medicines and follow-up.','Address dependence and social barriers without stigma.'],[['Exposure','Ongoing tobacco'],['Intervention','Supported cessation'],['Additional prevention','Vaccines and other exposure reduction']],[GO])
q('Which COPD phenotype particularly supports considering roflumilast after recurrent exacerbations despite inhaled treatment?', 'Chronic bronchitis with FEV1 below 50% predicted, especially with a prior severe event',[
 ('Mild episodic asthma without chronic bronchitis','That is not the usual COPD indication.'),('A patient seeking immediate rescue of acute bronchospasm','Roflumilast is maintenance anti-inflammatory treatment.'),('Every person with isolated low DLCO regardless of history','The evidence applies to a defined phenotype.')],
 'A selected oral add-on targets exacerbation risk', '**Roflumilast inhibits PDE4.**',['Weight loss, GI intolerance and psychiatric effects can limit use.','A low-weight or depressed patient needs particular review.'], '**Confirm optimization of basic care first.**',['It is not a bronchodilator rescue drug.','Track exacerbation benefit and tolerance.'],[['Phenotype','Chronic bronchitis/low FEV1'],['Target','PDE4'],['Concerns','Weight, GI and mood effects']],[GO])
q('Long-term azithromycin is considered for persistent COPD exacerbations. Which review is important before treatment?', 'QT risk, hearing, drug interactions and potential mycobacterial infection, with attention to resistance',[
 ('It is harmless and requires no baseline assessment','Cardiac, auditory and microbiological harms matter.'),('It replaces all bronchodilators','It is an add-on in selected patients.'),('It is the preferred rescue for every isolated breathless episode','Maintenance prevention and acute treatment differ.')],
 'An antibiotic prevention strategy has noninfectious and resistance costs', '**GOLD considers macrolides in selected frequent exacerbators, with evidence particularly favorable in former smokers.**',['Selection and duration require review.','Occult NTM disease can make unplanned macrolide monotherapy problematic.'], '**Use a defined monitoring and reassessment plan.**',['Review hearing symptoms and ECG context.','Do not continue indefinitely without evidence of benefit.'],[['Purpose','Selected exacerbation prevention'],['Safety','QT and hearing'],['Microbiology','Resistance and NTM context']],[GO])
q('A COPD patient with eosinophils repeatedly above 300 continues to exacerbate despite optimized triple therapy. Which statement reflects newer GOLD options?', 'Selected patients may qualify for a biologic such as dupilumab or mepolizumab, with phenotype-specific evidence',[
 ('Biologics are never used in COPD under current guidance','The evidence and recommendations have expanded.'),('Every COPD patient should receive any asthma biologic','Eligibility and outcome evidence are specific.'),('The agents have proven identical benefit in every phenotype','Direct and phenotype-specific evidence differ.')],
 'Type 2 inflammation can be relevant beyond an asthma diagnosis', '**Dupilumab evidence particularly includes chronic bronchitis with elevated eosinophils.**',['Mepolizumab has evidence with and without chronic bronchitis in the eligible eosinophilic context.','Local authorization and prior treatment requirements apply.'], '**Use specialist selection and measurable goals.**',['Confirm adherence and other exacerbation causes.','Do not extrapolate from an antibody target alone.'],[['Setting','Persistent events on optimized triple'],['Biomarker','Eosinophils around at least 300'],['Selection','Specific phenotype and local criteria']],[GO,ME],'clinical_scenario')
